#include "web_admin.h"
#include <esp_system.h>

namespace {
String trimValue(String value){value.trim();return value;}
}

void AcmWebAdmin::begin(ConfigStore& config, PinStore& pins, AlarmCore& core, KeypadManager& keypads, EventLogger& logger, const String& hostname, const String& device_id){config_=&config;pins_=&pins;core_=&core;keypads_=&keypads;logger_=&logger;hostname_=hostname;device_id_=device_id;server_.begin();}
void AcmWebAdmin::close(){if(active_)client_.stop();active_=false;request_="";body_="";}
String AcmWebAdmin::htmlEscape(const String& value) const {String out;for(uint16_t i=0;i<value.length();++i){switch(value[i]){case '&':out+="&amp;";break;case '<':out+="&lt;";break;case '>':out+="&gt;";break;case '"':out+="&quot;";break;case '\'':out+="&#39;";break;default:out+=value[i];}}return out;}
String AcmWebAdmin::urlDecode(const String& value) const {String out;for(uint16_t i=0;i<value.length();++i){if(value[i]=='+')out+=' ';else if(value[i]=='%'&&i+2<value.length()){char hex[3]={value[i+1],value[i+2],0};out+=static_cast<char>(strtol(hex,nullptr,16));i+=2;}else out+=value[i];}return out;}
String AcmWebAdmin::field(const String& key) const {String needle=key+"=";int p=body_.indexOf(needle);if(p<0)return "";p+=needle.length();int e=body_.indexOf('&',p);return urlDecode(e<0?body_.substring(p):body_.substring(p,e));}
String AcmWebAdmin::token() const {uint8_t bytes[16];esp_fill_random(bytes,sizeof(bytes));String value;for(uint8_t i=0;i<sizeof(bytes);++i){if(bytes[i]<16)value+='0';value+=String(bytes[i],HEX);}return value;}
AcmWebAdmin::Session* AcmWebAdmin::findSession(const String& id){if(!id.length())return nullptr;for(auto& session:sessions_)if(session.used&&session.id==id)return &session;return nullptr;}
AcmWebAdmin::Session* AcmWebAdmin::createSession(){Session* free=nullptr;for(auto& session:sessions_){if(!session.used){free=&session;break;}if(!free||session.last<free->last)free=&session;}if(!free)return nullptr;free->used=true;free->id=token();free->csrf=token();free->last=millis();return free;}
void AcmWebAdmin::expire(Session& session){session.used=false;session.id="";session.csrf="";session.last=0;}
bool AcmWebAdmin::parseRequest(){request_="";body_="";cookie_="";uint32_t deadline=millis()+100;while(client_.available()&&request_.length()<3072){char c=static_cast<char>(client_.read());request_+=c;if(request_.endsWith("\r\n\r\n"))break;if(static_cast<int32_t>(millis()-deadline)>=0)break;}int line=request_.indexOf("\r\n");if(line<0)return false;String first=request_.substring(0,line);int sp=first.indexOf(' '),sp2=first.indexOf(' ',sp+1);if(sp<0||sp2<0)return false;method_=first.substring(0,sp);String target=first.substring(sp+1,sp2);int q=target.indexOf('?');path_=q<0?target:target.substring(0,q);if(path_.length()>64)return false;int cookie=request_.indexOf("Cookie:");if(cookie>=0){int b=cookie+7,e=request_.indexOf("\r\n",b);String lineValue=request_.substring(b,e<0?request_.length():e);int sid=lineValue.indexOf("ACMSESSION=");if(sid>=0){sid+=11;int end=lineValue.indexOf(';',sid);cookie_=lineValue.substring(sid,end<0?lineValue.length():end);}}int content=request_.indexOf("Content-Length:");int length=0;if(content>=0)length=request_.substring(content+15,request_.indexOf("\r\n",content)).toInt();if(length>2048)return false;int headerEnd=request_.indexOf("\r\n\r\n");if(length&&headerEnd>=0){body_=request_.substring(headerEnd+4);uint32_t end=millis()+100;while(body_.length()<length&&client_.available()&&millis()<end)body_+=static_cast<char>(client_.read());}return true;}
bool AcmWebAdmin::authenticated(Session*& session){session=findSession(cookie_);if(!session)return false;const uint32_t now=millis();if(static_cast<uint32_t>(now-session->last)>SESSION_IDLE_MS){expire(*session);audit("WEB_SESSION_EXPIRED");return false;}session->last=now;return true;}
bool AcmWebAdmin::requireCsrf(const Session& session) const {return method_=="POST"&&field("csrf")==session.csrf;}
void AcmWebAdmin::response(uint16_t status,const String& type,const String& content,const String& extra){client_.print(String("HTTP/1.1 ")+String(status)+" "+(status==200?"OK":status==303?"See Other":status==400?"Bad Request":"Unauthorized")+"\r\nContent-Type: "+type+"\r\nContent-Length: "+String(content.length())+"\r\nConnection: close\r\n"+extra+"\r\n"+content);close();}
void AcmWebAdmin::redirect(const String& location,const String& extra){response(303,"text/plain","redirect",String("Location: ")+location+"\r\n"+extra);}
void AcmWebAdmin::audit(const String& event,const String& metadata){if(logger_)logger_->log(event,metadata);}
String AcmWebAdmin::typeName(SensorType type) const{return type==SensorType::MOTION?"MOTION":"OPENING";}
String AcmWebAdmin::areaName(uint16_t id) const {if(!id)return "Unassigned";for(uint8_t i=0;i<config_->areaCount();++i)if(config_->area(i).id==id)return config_->area(i).name;return "Unknown";}
String AcmWebAdmin::statusHeader() const {return String("<header><b>ACM</b> &nbsp; Alarm: ")+htmlEscape(acm_protocol::alarmStateName(core_->snapshot().state))+" &nbsp; HCM: "+(core_->snapshot().trouble_flags?"Trouble":"Connected/standalone")+"</header>";}
String AcmWebAdmin::nav(const String& active) const {String out="<nav>";const char* tabs[]={"channels","outputs","keypads","pins","areas","system","logs"};for(const char* tab:tabs)out+="<a href='/"+String(tab)+"'>"+String(tab[0]-32)+String(tab+1)+"</a> ";out+="<a href='/logout'>Logout</a></nav>";return out;}
void AcmWebAdmin::loginPage(const String& error){String html="<!doctype html><meta name='viewport' content='width=device-width'><title>ACM Login</title><h1>ACM Administration</h1>";if(error.length())html+="<p>"+htmlEscape(error)+"</p>";html+="<form method='post' action='/login'><label>Master PIN <input type='password' name='pin' maxlength='12' inputmode='numeric'></label><button>Login</button></form>";response(200,"text/html",html);}
void AcmWebAdmin::page(const String& tab){String html="<!doctype html><meta name='viewport' content='width=device-width'><title>ACM "+tab+"</title><style>body{font:16px sans-serif;max-width:1100px;margin:auto}table{border-collapse:collapse;width:100%}td,th{padding:4px;border-bottom:1px solid #ccc}nav{padding:12px 0}input,select{max-width:180px}</style>"+statusHeader()+nav(tab)+"<main><h1>"+htmlEscape(tab)+"</h1>";
  if(tab=="channels"){html+="<table><tr><th>Channel</th><th>Name</th><th>Area</th><th>Type</th><th>Live State</th><th></th></tr>";for(uint8_t i=0;i<ConfigStore::MAX_CHANNELS;++i){const auto& c=config_->channel(i);html+="<tr><form method='post'><td>"+String(i+1)+"<input type='hidden' name='action' value='channel'><input type='hidden' name='index' value='"+String(i+1)+"'><input type='hidden' name='csrf' value='"+htmlEscape(findSession(cookie_)->csrf)+"'></td><td><input name='name' maxlength='48' value='"+htmlEscape(c.name)+"'></td><td><select name='area'><option value='0'>Unassigned</option>";for(uint8_t a=0;a<config_->areaCount();++a)html+="<option value='"+String(config_->area(a).id)+"'"+String(c.area_id==config_->area(a).id?" selected":"")+">"+htmlEscape(config_->area(a).name)+"</option>";html+="</select></td><td><select name='type'><option"+String(c.type==SensorType::OPENING?" selected":"")+">OPENING</option><option"+String(c.type==SensorType::MOTION?" selected":"")+">MOTION</option></select></td><td>"+String((core_->snapshot().open_bitmap[i/32]&(1u<<(i%32)))?"OPEN":"CLOSED")+"</td><td><button>Save</button></td></form></tr>";}html+="</table>";}
  else if(tab=="outputs"){html+="<table><tr><th>Relay</th><th>Name</th><th>Area</th><th>Siren</th><th>Current State</th><th></th></tr>";for(uint8_t i=0;i<ConfigStore::MAX_RELAYS;++i){const auto& r=config_->relay(i);html+="<tr><form method='post'><td>"+String(i+1)+"<input type='hidden' name='action' value='relay'><input type='hidden' name='index' value='"+String(i+1)+"'><input type='hidden' name='csrf' value='"+findSession(cookie_)->csrf+"'></td><td><input name='name' maxlength='48' value='"+htmlEscape(r.name)+"'></td><td><input name='area' value='"+String(r.area_id)+"'></td><td><input type='checkbox' name='siren'"+(r.siren?" checked":"")+"></td><td>"+((r.siren&&core_->snapshot().state==AlarmState::TRIGGERED)?"ACTIVE":"INACTIVE")+"</td><td><button>Save</button></td></form></tr>";}html+="</table>";}
  else if(tab=="areas"){html+="<form method='post'><input type='hidden' name='action' value='area_add'><input type='hidden' name='csrf' value='"+findSession(cookie_)->csrf+"'><input name='name' maxlength='48' placeholder='Specify Other Area'><button>Add Area</button></form><table><tr><th>ID</th><th>Name</th></tr>";for(uint8_t i=0;i<config_->areaCount();++i){const auto& a=config_->area(i);html+="<tr><form method='post'><td>"+String(a.id)+"<input type='hidden' name='action' value='area_rename'><input type='hidden' name='id' value='"+String(a.id)+"'><input type='hidden' name='csrf' value='"+findSession(cookie_)->csrf+"'></td><td><input name='name' maxlength='48' value='"+htmlEscape(a.name)+"'><button>Rename</button></td></form></tr>";}html+="</table>";}
  else if(tab=="pins"){html+="<p>PIN values are never displayed. Every mutation requires the current Master PIN.</p><form method='post'><input type='hidden' name='action' value='pin_add'><input type='hidden' name='csrf' value='"+findSession(cookie_)->csrf+"'><input name='name' maxlength='48' placeholder='Friendly Name'><input type='password' name='newpin' maxlength='12' placeholder='New PIN'><input type='password' name='master' maxlength='12' placeholder='Master PIN'><button>Add Standard PIN</button></form><table><tr><th>Friendly Name</th><th>Role</th><th>Enabled</th><th>PIN</th><th>Actions</th></tr>";for(uint8_t i=0;i<pins_->count();++i){html+="<tr><td>"+htmlEscape(pins_->name(i))+"</td><td>"+(pins_->role(i)==PinRole::MASTER?"MASTER":"STANDARD")+"</td><td>"+(pins_->enabled(i)?"YES":"NO")+"</td><td>****</td><td>";if(i>0)html+="<form method='post'><input type='hidden' name='action' value='pin_enable'><input type='hidden' name='id' value='"+String(i)+"'><input type='hidden' name='csrf' value='"+findSession(cookie_)->csrf+"'><input type='hidden' name='enabled' value='"+(pins_->enabled(i)?"0":"1")+"'><input type='password' name='master' maxlength='12'><button>"+(pins_->enabled(i)?"Disable":"Enable")+"</button></form>";html+="</td></tr>";}html+="</table>";}
  else if(tab=="keypads"){html+="<p><form method='post'><input type='hidden' name='action' value='keypad_add'><input type='hidden' name='csrf' value='"+findSession(cookie_)->csrf+"'><input name='ip' maxlength='15' placeholder='IPv4 address'><button>Add Keypad</button></form></p><table><tr><th>Name</th><th>IP</th><th>MAC</th><th>Area</th><th>Status</th><th>Firmware</th><th></th></tr>";for(uint8_t i=0;i<config_->keypadCount();++i){const auto& k=config_->keypad(i);html+="<tr><td>"+htmlEscape(k.name)+"</td><td>"+htmlEscape(k.ip)+"</td><td>"+htmlEscape(k.mac)+"</td><td>"+htmlEscape(areaName(k.area_id))+"</td><td>"+(keypads_->online(i)?"Online":"Offline")+"</td><td>"+htmlEscape(k.firmware)+"</td><td><form method='post' onsubmit='return confirm(\"Remove keypad?\")'><input type='hidden' name='action' value='keypad_remove'><input type='hidden' name='index' value='"+String(i)+"'><input type='hidden' name='csrf' value='"+findSession(cookie_)->csrf+"'><button>Remove</button></form></td></tr>";}html+="</table>";}
  else if(tab=="logs"){html+="<pre>"+htmlEscape(logger_->recentLines(100))+"</pre>";}
  else if(tab=="system"){const auto& s=core_->snapshot();const char* configStatus=config_->status()==ConfigStatus::FRESH?"FRESH":config_->status()==ConfigStatus::CURRENT?"CURRENT":config_->status()==ConfigStatus::MIGRATED?"MIGRATED":"RECOVERY_REQUIRED";uint8_t online=0;for(uint8_t i=0;i<config_->keypadCount();++i)if(keypads_->online(i))++online;html+="<dl><dt>Hostname</dt><dd>"+htmlEscape(hostname_)+"</dd><dt>Device ID</dt><dd>"+htmlEscape(device_id_)+"</dd><dt>IP Address</dt><dd>"+Ethernet.localIP().toString()+"</dd><dt>Alarm State</dt><dd>"+String(acm_protocol::alarmStateName(s.state))+"</dd><dt>Countdown</dt><dd>"+String(s.countdown_seconds)+"</dd><dt>HCM Connection</dt><dd>"+(s.trouble_flags?"Trouble":"OK / standalone")+"</dd><dt>Time Sync State</dt><dd>"+(logger_->timeSynchronized()?"Synchronized":"Unsynchronized / stale")+"</dd><dt>SD</dt><dd>"+(logger_->sdFailed()?"FAILED / RETRYING":"OK")+"</dd><dt>MCP/I2C</dt><dd>Initialized</dd><dt>Configuration</dt><dd>"+String(configStatus)+"</dd><dt>Credential Status</dt><dd>"+(pins_->credentialReprovisionRequired()?"Credential reprovisioning required":"Ready")+"</dd><dt>Enrolled Keypads</dt><dd>"+String(config_->keypadCount())+"</dd><dt>Online Keypads</dt><dd>"+String(online)+"</dd><dt>Offline Keypads</dt><dd>"+String(config_->keypadCount()-online)+"</dd></dl>";}
  html+="</main>";response(200,"text/html",html);}
void AcmWebAdmin::applyMutation(Session& session){if(!requireCsrf(session)){response(400,"text/plain","CSRF rejected");return;}const String action=field("action");if(action=="channel"){ChannelRecord value=config_->channel(field("index").toInt()-1);value.name=field("name");value.area_id=static_cast<uint16_t>(field("area").toInt());value.type=field("type")=="MOTION"?SensorType::MOTION:SensorType::OPENING;if(config_->saveChannel(value)){core_->setSensorType(value.index-1,value.type);audit("CHANNEL_CONFIG_CHANGED",String("Channel=")+String(value.index));}}
  else if(action=="relay"){RelayRecord value=config_->relay(field("index").toInt()-1);value.name=field("name");value.area_id=static_cast<uint16_t>(field("area").toInt());value.siren=field("siren")=="on";if(config_->saveRelay(value))audit("RELAY_CONFIG_CHANGED",String("Relay=")+String(value.index));}
  else if(action=="area_add"){String name=field("name");if(name.length()&&name.length()<=48){if(config_->addArea(name))audit("AREA_ADDED",String("Area=")+name);}}
  else if(action=="area_rename"){String name=field("name");if(name.length()&&name.length()<=48&&config_->renameArea(field("id").toInt(),name))audit("AREA_RENAMED",String("Area=")+name);}
  else if(action=="pin_add"){String master=field("master"),pin=field("newpin"),name=field("name");if(pins_->addPin(master,pin,name))audit("PIN_ADDED",String("PIN=")+name);master="";pin="";}
  else if(action=="pin_rename"){const uint8_t id=field("id").toInt();if(pins_->renamePin(field("master"),id,field("name")))audit("PIN_RENAMED",String("PIN=")+pins_->name(id));}
  else if(action=="pin_reset"){const uint8_t id=field("id").toInt();String newPin=field("newpin");if(pins_->resetPin(field("master"),id,newPin))audit("PIN_RESET",String("PIN=")+pins_->name(id));newPin="";}
  else if(action=="pin_remove"){const uint8_t id=field("id").toInt();if(pins_->removePin(field("master"),id))audit("PIN_REMOVED",String("PIN=")+pins_->name(id));}
  else if(action=="master_change"){String oldPin=field("master"),newPin=field("newpin");if(pins_->changeMaster(oldPin,newPin))audit("MASTER_PIN_CHANGED","PIN=Master");oldPin="";newPin="";}
  else if(action=="pin_enable"){const uint8_t id=field("id").toInt();const bool enabled=field("enabled")=="1";if(pins_->setEnabled(field("master"),id,enabled))audit(enabled?"PIN_ENABLED":"PIN_DISABLED",String("PIN=")+pins_->name(id));}
  else if(action=="keypad_add"){IPAddress ip;if(ip.fromString(field("ip"))){if(keypads_->enrollKeypad(ip))audit("KEYPAD_ADDED");}}
  redirect("/"+field("return"));}
void AcmWebAdmin::handle(){if(!parseRequest()){response(400,"text/plain","Bad request");return;}if(path_=="/login"){if(method_=="GET"){loginPage();return;}if(method_!="POST"||millis()-last_failure_<1000){loginPage("Try again shortly");return;}String pin=field("pin");PinAuthResult auth=pins_->authenticate(pin);pin="";if(auth.valid&&auth.role==PinRole::MASTER){Session* session=createSession();if(session){audit("WEB_LOGIN_SUCCESS",String("PIN=")+auth.friendly_name);redirect("/channels",String("Set-Cookie: ACMSESSION=")+session->id+"; HttpOnly; SameSite=Strict; Path=/\r\n");return;}}last_failure_=millis();++failures_;audit("WEB_LOGIN_FAILED");loginPage("Login failed");return;}
  if(path_=="/logout"){Session* session=findSession(cookie_);if(session)expire(*session);audit("WEB_LOGOUT");redirect("/login","Set-Cookie: ACMSESSION=; Max-Age=0; HttpOnly; SameSite=Strict; Path=/\r\n");return;}
  Session* session=nullptr;if(!authenticated(session)){redirect("/login");return;}if(method_=="POST"){applyMutation(*session);return;}if(path_=="/"||path_=="/channels")page("channels");else if(path_=="/outputs")page("outputs");else if(path_=="/areas")page("areas");else if(path_=="/keypads")page("keypads");else if(path_=="/pins")page("pins");else if(path_=="/system")page("system");else if(path_=="/logs")page("logs");else response(400,"text/plain","Unknown page");}
void AcmWebAdmin::tick(uint32_t now){(void)now;if(!active_){EthernetClient candidate=server_.available();if(candidate){client_=candidate;active_=true;request_started_=millis();}}if(active_){if(millis()-request_started_>250){close();return;}if(client_.available())handle();}}
